    :mercaptopurine => [
        (drug_name = "mercaptopurine", recommendation = "Neither TPMT or NUDT15 phenotype could be assigned based on genotyping performed. Consider evaluating TPMT erythrocyte activity to assess TPMT phenotype. If thiopurines are required and either TPMT or NUDT15 status is unknown, monitor closely for toxicity.", classification = "Strong", implications = "TPMT: n/a; NUDT15: n/a", phenotypes = "TPMT: Indeterminate; NUDT15: Indeterminate", lookup_key = "TPMT: Indeterminate; NUDT15: Indeterminate", source = :cpic),
        (drug_name = "mercaptopurine", recommendation = "Based NUDT15 status, start with reduced starting doses (30%-80% of normal dose) if normal starting dose is ≥75 mg/m2/day or ≥ 1.5 mg/kg/day (e.g., start at 22.5-60 mg/m2/day or 0.45-1.2 mg/kg/day) and adjust doses of mercaptopurine based on degree of myelosuppression and disease-specific guidelines. Allow 2-4 weeks to reach steady-state after each dose adjustment. If myelosuppression occurs, and depending on other therapy, emphasis should be on reducing mercaptopurine over other agents (PMID 20354201, 18685564, 8857546, 18987654, 20010622, 16401827, 11302950, 16530532, 9634537). If normal starting dose is already < 75 mg/m2/day or < 1.5 mg/kg/day, dose reduction may not be recommended. TPMT phenotype could not be assigned based on genotyping. Consider evaluating TPMT erythrocyte activity to assess TPMT phenotype. If thiopurines are required and either TPMT or NUDT15 status is unknown, monitor closely for toxicity.", classification = "Strong", implications = "TPMT: n/a; NUDT15: Increased risk of thiopurine-related leukopenia, neutropenia, myelosuppression", phenotypes = "TPMT: Indeterminate; NUDT15: Intermediate Metabolizer", lookup_key = "TPMT: Indeterminate; NUDT15: Intermediate Metabolizer", source = :cpic),
        (drug_name = "mercaptopurine", recommendation = "Based on NUDT15 status, start with normal starting dose (e.g., 75 mg/m2/day or 1.5 mg/kg/day) and adjust doses of mercaptopurine (and of any other myelosuppressive therapy) without any special emphasis on mercaptopurine compared to other agents. Allow at least 2 weeks to reach steady-state after each dose adjustment (PMID 20354201, 16401827, 11302950). TPMT phenotype could not be assigned based on genotyping performed. Consider evaluating TPMT erythrocyte activity to assess TPMT phenotype. If thiopurines are required and TPMT status is unknown, monitor closely for toxicity.", classification = "Strong", implications = "TPMT: n/a; NUDT15: Normal risk of thiopurine-related leukopenia, neutropenia, myelosuppression", phenotypes = "TPMT: Indeterminate; NUDT15: Normal Metabolizer", lookup_key = "TPMT: Indeterminate; NUDT15: Normal Metabolizer", source = :cpic),
        (drug_name = "mercaptopurine", recommendation = "Based on NUDT15 status, for malignancy, initiate dose at 10 mg/m2/day and adjust dose based on myelosuppression and disease-specific guidelines. Allow 4-6 weeks to reach steady state after each dose adjustment. If myelosuppression occurs, emphasis should be on reducing mercaptopurine over other agents. For non-malignant conditions, consider alternative non-thiopurine immunosuppressant therapy (PMID 20354201, 1960624, 11302950, 16530532). TPMT phenotype could not be assigned based on genotyping performed. Consider evaluating TPMT erythrocyte activity to assess TPMT phenotype. If thiopurines are required and TPMT status is unknown, monitor closely for toxicity.", classification = "Strong", implications = "TPMT: n/a; NUDT15: Greatly increased risk of thiopurine-related leukopenia, neutropenia, myelosuppression", phenotypes = "TPMT: Indeterminate; NUDT15: Poor Metabolizer", lookup_key = "TPMT: Indeterminate; NUDT15: Poor Metabolizer", source = :cpic),
